// @ts-ignore — runtime module from nodejs_compat (always on); generated
// projects don't install @types/node, so it is typed at its use below.
import { AsyncLocalStorage } from 'node:async_hooks';

export type TimingMarks = Array<[name: string, ms: number]>;

const __timing: { getStore(): TimingMarks | undefined; run<R>(store: TimingMarks, fn: () => R): R } = new AsyncLocalStorage();

/** At most this many marks per request (a loop cannot grow the header without bound). */
const MAX_MARKS = 64;

/** Run `fn` with `marks` collecting this request's stage timings. */
export function runWithRequestTiming<R>(marks: TimingMarks, fn: () => R): R {
  return __timing.run(marks, fn);
}

/** True inside a timed request. */
export function timingActive(): boolean {
  return __timing.getStore() !== undefined;
}

/** Record `ms` for stage `name` on the current request (no-op when timing is off). */
export function markTiming(name: string, ms: number): void {
  const marks = __timing.getStore();
  if (marks && marks.length < MAX_MARKS && Number.isFinite(ms)) marks.push([name, ms]);
}

/** Record the time since `started` (a performance.now() reading) as stage `name`. */
export function markSince(name: string, started: number): void {
  markTiming(name, performance.now() - started);
}

/** Time `fn` as stage `name` (no-op wrapper when timing is off). */
export async function timed<T>(name: string, fn: () => PromiseLike<T>): Promise<T> {
  const marks = __timing.getStore();
  if (!marks) return fn();
  const started = performance.now();
  try {
    return await fn();
  } finally {
    if (marks.length < MAX_MARKS) marks.push([name, performance.now() - started]);
  }
}

/** Sum marks by name, in first-seen order: [name, totalMs, count]. */
export function summarizeTiming(marks: TimingMarks): Array<[string, number, number]> {
  const out = new Map<string, [string, number, number]>();
  for (const [name, ms] of marks) {
    const row = out.get(name);
    if (row) { row[1] += ms; row[2] += 1; } else out.set(name, [name, ms, 1]);
  }
  return [...out.values()];
}

